# Check _to_dict_for_comparison
import semver
v = semver.VersionInfo(1, 2, 3)

print("Dict from tuple:", v._to_dict_for_comparison((1,2,3)))
try:
    print("Dict from str:", v._to_dict_for_comparison("1.2.3"))
except Exception as e:
    print(f"Dict from str -> {type(e).__name__}: {e}")

try:
    print("Dict from int:", v._to_dict_for_comparison(42))
except Exception as e:
    print(f"Dict from int -> {type(e).__name__}: {e}")
